ADMIN_PAGE = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#102b46"><title>CivicOne — Administration</title>
<style>
:root{--navy:#102b46;--teal:#0d8278;--ink:#172b3c;--muted:#657789;--line:#e4ebef;--bg:#f3f6f8}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px Inter,system-ui,-apple-system,"Segoe UI",sans-serif}header{background:var(--navy);color:white;padding:18px 0}.wrap{width:min(1120px,calc(100% - 36px));margin:auto}.bar{display:flex;align-items:center;justify-content:space-between}.brand{font-size:18px;font-weight:800}.brand small{display:block;color:#bdd0dc;font-size:10px;letter-spacing:1.3px;margin-top:3px}.bar a{color:#d8e6ee;text-decoration:none;font-size:12px}.main{padding:34px 0 60px}.eyebrow{font-size:10px;letter-spacing:1.6px;text-transform:uppercase;color:var(--teal);font-weight:800}.head{display:flex;justify-content:space-between;align-items:end;gap:15px;margin-bottom:22px}.head h1{margin:6px 0;font-size:30px;letter-spacing:-.8px}.muted{color:var(--muted);font-size:12px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:20px 0}.stat,.panel,.card{background:white;border:1px solid var(--line);border-radius:12px}.stat{padding:17px}.stat strong{display:block;font-size:25px;margin-bottom:3px}.stat span{font-size:11px;color:var(--muted)}.panel{padding:20px}.login{max-width:430px;margin:45px auto}.login h2{margin:0 0 8px}.field label{display:block;font-size:11px;font-weight:750;margin:15px 0 6px}.field input,.filter,select{width:100%;border:1px solid #d7e1e7;border-radius:8px;padding:11px;font:inherit;background:#fff}.btn{background:var(--teal);border:0;border-radius:8px;color:white;padding:11px 16px;font-weight:750;cursor:pointer}.login .btn{width:100%;margin-top:15px}.error{color:#b33d3d;font-size:12px;margin-top:10px}.toolbar{display:flex;gap:10px;margin-bottom:15px}.toolbar input{max-width:360px}.list{display:grid;gap:12px}.card{padding:18px}.cardtop{display:flex;justify-content:space-between;gap:15px;align-items:start}.ref{font-weight:800;color:#176c78;font-size:12px}.card h3{margin:6px 0;font-size:16px}.badge{display:inline-block;background:#edf4f5;color:#35586a;border-radius:30px;padding:6px 10px;font-size:10px;font-weight:800}.details{font-size:12px;line-height:1.7;color:#526779;margin:10px 0}.details b{color:#233e51}.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:13px}.actions select{width:auto;min-width:150px;padding:8px;font-size:12px}.empty{text-align:center;padding:35px;color:var(--muted)}.hidden{display:none!important}.notice{font-size:11px;color:#778896;line-height:1.6;margin-top:20px}@media(max-width:700px){.stats{grid-template-columns:repeat(2,1fr)}.head{display:block}.toolbar{flex-direction:column}.toolbar input{max-width:none}.cardtop{display:block}.badge{margin-top:9px}}
</style></head><body>
<header><div class="wrap bar"><div class="brand">CivicOne <small>ADMINISTRATION CONSOLE</small></div><a href="/">← Citizen portal</a></div></header>
<main class="wrap main">
<section id="loginPanel" class="panel login"><div class="eyebrow">Restricted workspace</div><h2>Administrator sign in</h2><p class="muted">Use the local administrator password configured for this demo server.</p><form id="loginForm" class="field"><label for="password">Administrator password</label><input id="password" type="password" autocomplete="current-password" required><button class="btn" type="submit">Sign in</button><div id="loginError" class="error"></div></form><p class="notice">Admin access is disabled until CIVICONE_ADMIN_PASSWORD is configured in the server environment. This prototype is intended for local academic demonstration only.</p></section>
<section id="dashboard" class="hidden"><div class="head"><div><div class="eyebrow">Operations overview</div><h1>Application management</h1><div class="muted">Review incoming requests and update their workflow status.</div></div><button class="btn" id="logout">Sign out</button></div>
<div class="stats"><div class="stat"><strong id="total">0</strong><span>Total applications</span></div><div class="stat"><strong id="submitted">0</strong><span>Submitted</span></div><div class="stat"><strong id="review">0</strong><span>Under review</span></div><div class="stat"><strong id="closed">0</strong><span>Approved / rejected</span></div></div>
<div class="panel"><div class="toolbar"><input id="search" class="filter" placeholder="Search reference, applicant or service"><select id="statusFilter" class="filter"><option value="">All statuses</option><option>Submitted</option><option>Under Review</option><option>Approved</option><option>Rejected</option></select><button class="btn" id="refresh">Refresh</button></div><div id="applications" class="list"></div></div>
<p class="notice">Applicant contact details are visible only inside this password-protected local admin session. Do not use real personal or sensitive information. Status changes are stored in the local application JSON file.</p></section>
</main>
<script>
const $=id=>document.getElementById(id);let apps=[];
async function api(url,opts={}){const r=await fetch(url,{...opts,headers:{'Content-Type':'application/json',...(opts.headers||{})}});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}
function showDashboard(){ $('loginPanel').classList.add('hidden');$('dashboard').classList.remove('hidden');load()}
function draw(){const q=$('search').value.toLowerCase(),st=$('statusFilter').value;const rows=apps.filter(a=>(!st||a.status===st)&&[a.reference,a.name,a.service,a.email].join(' ').toLowerCase().includes(q));$('total').textContent=apps.length;$('submitted').textContent=apps.filter(a=>a.status==='Submitted').length;$('review').textContent=apps.filter(a=>a.status==='Under Review').length;$('closed').textContent=apps.filter(a=>['Approved','Rejected'].includes(a.status)).length;
$('applications').innerHTML=rows.length?rows.map(a=>{const ref=esc(a.reference);return '<article class="card"><div class="cardtop"><div><div class="ref">'+ref+'</div><h3>'+esc(a.service)+'</h3><div class="muted">Submitted '+esc(a.submitted_at)+'</div></div><span class="badge">'+esc(a.status)+'</span></div><div class="details"><b>Applicant:</b> '+esc(a.name)+' · '+esc(a.email)+' · '+esc(a.mobile)+'<br><b>Request:</b> '+esc(a.details)+'</div><div class="actions"><label class="muted" for="s-'+ref+'">Update status</label><select id="s-'+ref+'"><option '+(a.status==='Submitted'?'selected':'')+'>Submitted</option><option '+(a.status==='Under Review'?'selected':'')+'>Under Review</option><option '+(a.status==='Approved'?'selected':'')+'>Approved</option><option '+(a.status==='Rejected'?'selected':'')+'>Rejected</option></select><button class="btn" data-save="'+ref+'">Save status</button><span class="muted" id="msg-'+ref+'"></span></div></article>'}).join(''):'<div class="empty">No applications match this filter.</div>';
document.querySelectorAll('[data-save]').forEach(b=>b.addEventListener('click',async()=>{const ref=b.dataset.save,msg=$('msg-'+ref),status=$('s-'+ref).value;b.disabled=true;msg.textContent='Saving…';try{await api('/api/admin/status',{method:'POST',body:JSON.stringify({reference:ref,status})});msg.textContent='Updated';await load()}catch(e){msg.textContent=e.message}finally{b.disabled=false}}))}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function load(){try{apps=(await api('/api/admin/applications')).applications;draw()}catch(e){if(e.message.includes('sign-in')){ $('dashboard').classList.add('hidden');$('loginPanel').classList.remove('hidden')}else $('applications').textContent=e.message}}
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();$('loginError').textContent='Signing in…';try{await api('/api/admin/login',{method:'POST',body:JSON.stringify({password:$('password').value})});$('password').value='';showDashboard()}catch(err){$('loginError').textContent=err.message}});
$('logout').addEventListener('click',async()=>{await api('/api/admin/logout',{method:'POST',body:'{}'});$('dashboard').classList.add('hidden');$('loginPanel').classList.remove('hidden')});
$('refresh').addEventListener('click',load);$('search').addEventListener('input',draw);$('statusFilter').addEventListener('change',draw);
api('/api/admin/applications').then(d=>{apps=d.applications;showDashboard()}).catch(()=>{});
</script></body></html>"""
